#include "symrep_bootstrap.hpp"
using namespace symrep;
int main(int argc,char**argv){try{require(argc==8,"usage seam_origin_residual OUT prefix_weight origin.wxf localTF.wxf stem halt|all blocksize");fs::path out=argv[1];size_t w=std::stoul(argv[2]),block=std::stoul(argv[7]);std::string stem=argv[5];bool halt=std::string(argv[6])=="halt";auto start=std::chrono::steady_clock::now();auto f=read(out/("FEC_"+std::to_string(w)+".wxf"));size_t nf=f.dim(0),no=f.dim(1);auto o=read_matrix(argv[3]),c=read_matrix(argv[4]);require(o.nrow==nf&&o.ncol==175&&c.ncol==88*175,"inputdims");auto ct=transpose(c);c.clear();Mat slices(no*88,nf);for(size_t b=0;b<nf;++b)for(size_t p=f.rowptr()[b];p<f.rowptr()[b+1];++p){auto i=f.index(p);slices[i[0]*88+i[1]].push_back(index(b),f.val(p));}f.clear();Mat result(no,ct.ncol);std::cout<<"READY prefix="<<nf<<" older="<<no<<" localrank="<<ct.ncol<<" nnz="<<slices.nnz()<<" seconds="<<seconds(start)<<std::endl;
 size_t done=0;bool pass=true;size_t witnessOld=0,witnessLocal=0;Q witness;
 for(size_t first=0;first<no;first+=block){size_t count=std::min(block,no-first);Mat part(count*88,nf);for(size_t i=0;i<part.nrow;++i)part[i]=std::move(slices[first*88+i]);auto h=mul(part,o);part.clear();Mat joined(count,88*175);for(size_t i=0;i<h.nrow;++i)for(auto[j,x]:h[i])joined[i/88].push_back(index((i%88)*175+j),x);h.clear();auto r=mul(joined,ct);for(size_t i=0;i<count;++i){result[first+i]=std::move(r[i]);if(pass&&result[first+i].nnz()){pass=false;witnessOld=first+i;witnessLocal=result[first+i](0);witness=result[first+i][0];}}done=first+count;if(first==0||done%256==0||done==no)std::cout<<"BLOCK checked="<<done<<" nonzero_rows="<<(pass?0:1)<<" seconds="<<seconds(start)<<std::endl;if(halt&&!pass)break;}
 write(out/(stem+"_residual.wxf"),result);std::ofstream j(out/(stem+".json"));j<<"{\"prefix_weight\":"<<w<<",\"older_context_count\":"<<no<<",\"checked_contexts\":"<<done<<",\"condition_rank\":"<<ct.ncol<<",\"all_checked_exact_zero\":"<<(pass?"true":"false")<<",\"complete_scan\":"<<(done==no?"true":"false")<<",\"nonzero_coefficients\":"<<result.nnz()<<",\"seconds\":"<<seconds(start)<<",\"F4_target_read\":false";if(!pass)j<<",\"first_witness\":{\"older_basis_index\":"<<witnessOld+1<<",\"condition_index\":"<<witnessLocal+1<<",\"coefficient\":\""<<witness<<"\"}";j<<"}\n";std::cout<<"COMPLETE checked="<<done<<" pass="<<pass<<" nnz="<<result.nnz()<<" seconds="<<seconds(start)<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
